[7381]={["atomIDs"]={"7381:description:1-87","7381:description:89-147","7381:description:149-251","7381:description:256-298","7381:description:303-384","7381:description:389-421","7381:description:423-458","7381:description:463-472","7381:objective:1-96","7381:objective:101-176"},["opening"]="Laggrond doubted that Korrak would stay dead. His suspicion of Winterax magic prompted a standing order: if the leader returned, his skull was to be brought back as firmer proof.",["pending"]="{actor} would watch for Korrak's return and recover his skull if he reappeared.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Laggrond the skull requested for Korrak's return.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="5fc889b54c92d0f27c96ec3e1f46b732409466033222da816622fa85cb498682",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7382]={["atomIDs"]={"7382:description:1-54","7382:description:56-97","7382:description:99-206","7382:description:211-238","7382:description:240-360","7382:description:365-458","7382:objective:1-96","7382:objective:101-178"},["opening"]="Haggerdin worried that the Winterax might restore their fallen leader. His precautions called for Korrak's skull if he appeared again, with the burning of the body ordered separately rather than assumed.",["pending"]="{actor} would seek Korrak if he returned and take the skull to Haggerdin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Korrak's skull to Lieutenant Haggerdin.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="88791c172a591b919c4031d26aba349b6d95dff3866c6b22ea05b43e648bf382",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7385]={["aftermath"]="Thurloga intended to mix it with the earlier offerings; the Ice Lord's arrival remained conditional on completing the whole offering.",["atomIDs"]={"7385:description:1-86","7385:description:88-139","7385:objective:1-4"},["endingAtomIDs"]={"7385:completion:1-39","7385:completion:41-100","7385:completion:102-214"},["objectiveSummary"]="Offer enemy blood to Primalist Thurloga.",["opening"]="Thurloga accepted larger offerings of enemy blood as the Frostwolves prepared their appeal to the Ice Lord. A gallon joined a stockpile whose eventual completion still mattered to the summoning.",["pending"]="{actor} would make a larger blood offering to Primalist Thurloga.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Thurloga with the larger offering of blood.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="b7c4723b2df20606a43b6d5fc9f616a1bbec2eff9b125839e078ed3d42101ef2",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7386]={["aftermath"]="Renferal planned to summon the Forest Lord when enough power had been amassed; this offering alone did not establish that arrival.",["atomIDs"]={"7386:description:1-79","7386:description:200-237","7386:description:81-195","7386:objective:1-4"},["endingAtomIDs"]={"7386:completion:1-14","7386:completion:16-104","7386:completion:106-225"},["objectiveSummary"]="Offer Frostwolf storm crystals to Arch Druid Renferal.",["opening"]="Renferal welcomed clusters of storm crystals gathered during long periods of fighting. Their power could be joined to the Circle's existing magic, building toward a call to the Forest Lord.",["pending"]="{actor} would offer the crystal cluster to Arch Druid Renferal.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} entrusted the crystal cluster to Renferal.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="1e48eb75c8eef249519d322610dc98ca2e69a915800cf3290d1932d9a0253e65",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7401]={["atomIDs"]={"7401:description:1-100","7401:description:105-283","7401:description:288-350","7401:objective:1-75","7401:objective:80-116","7401:objective:118-185"},["opening"]="Yazra Bloodsnarl's order singled out opposing dwarves for a particularly brutal trophy. A spine returned to Frostwolf Keep would serve as proof under her command.",["pending"]="{actor} would bring Yazra a dwarf spine from the opposing force.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the requested spine to Sergeant Yazra Bloodsnarl.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="3a3d8f376169d46e9f3223f8a51a14b28cb86cc22010b7b4153a19e9b303cfe9",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7402]={["atomIDs"]={"7402:description:1-155","7402:description:160-289","7402:description:294-316","7402:objective:1-73","7402:objective:78-161"},["opening"]="Noreg Stormpike demanded a tusk or tooth from opposing orcs as evidence of service. His order extended to every able-bodied Stormpike soldier on the field.",["pending"]="{actor} would bring Noreg an orc tooth from the fighting.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the tooth to Corporal Noreg Stormpike.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="fd07f3fd3fc3f51b15437c8bf549b54c7af9f5ea4b69581658e9b5b660f4bbb2",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7441]={["aftermath"]="Azj'Tordin cursed the thief and offered what little he had in thanks.",["atomIDs"]={"7441:description:1-54","7441:description:56-121","7441:description:123-244","7441:description:249-381","7441:description:386-429","7441:description:434-487","7441:objective:1-49","7441:objective:51-142","7441:objective:147-245"},["endingAtomIDs"]={"7441:completion:1-18","7441:completion:20-51","7441:completion:53-101","7441:completion:103-143"},["opening"]="An imp had robbed Azj'Tordin during his escape from the fallen Prince. The key no longer interested the elder, but he desperately wanted his stolen incantations back.",["pending"]="{actor} meant to recover the book from Pusillin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Azj'Tordin's Book of Incantations.",["sourceHash"]="6e5de3042136a6e87e9c265e582a7e3bbc4e882c743237be394cfbb4ffbaf058",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7461]={["aftermath"]="The ancient thanked the hero for the work.",["atomIDs"]={"7461:description:1-22","7461:description:24-57","7461:description:62-94","7461:description:96-142","7461:description:144-213","7461:description:215-252","7461:description:254-313","7461:description:315-363","7461:objective:1-92","7461:objective:94-188","7461:objective:193-277","7461:objective:279-328","7461:objective:333-414"},["endingAtomIDs"]={"7461:completion:1-19"},["opening"]="The ancient sought an end to Dire Maul's madness. Bringing down the pylon guardians would expose Immol'thar, and the demon's loss would leave the Prince weakened for the final confrontation.",["pending"]="{actor} intended to disable the pylons, defeat Immol'thar, and confront Tortheldrin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the defeat of Immol'thar and Tortheldrin after lowering the pylons.",["sourceHash"]="a053e1177887017ca1d0fc9cbe432b26a158fe07e25dba849ca4b87d2b3466ee",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7462]={["aftermath"]="The opened chest revealed the treasure within.",["atomIDs"]={"7462:description:1-86","7462:description:88-122","7462:objective:1-65","7462:objective:67-84"},["endingAtomIDs"]={"7462:completion:1-29"},["opening"]="The ancient directed the return to the Athenaeum. A chest beneath its stairway held the promised acknowledgment.",["pending"]="{actor} planned to find the hidden chest in the library.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found and opened the chest beneath the stairway.",["sourceHash"]="64886ea5b1c3225ebd2286313ec96f7ca92ede555b4ea0f20affc179a88a45ab",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7463]={["aftermath"]="Lydros welcomed the sample, then struggled to remember the visitor and the reward he had promised.",["atomIDs"]={"7463:description:1-10","7463:description:12-25","7463:description:27-65","7463:description:67-93","7463:description:95-104","7463:description:109-191","7463:description:196-213","7463:description:218-253","7463:description:255-309","7463:description:311-342","7463:description:347-443","7463:description:445-499","7463:objective:1-85","7463:objective:87-159"},["endingAtomIDs"]={"7463:completion:1-10","7463:completion:12-29","7463:completion:31-48","7463:completion:50-81","7463:completion:83-88","7463:completion:90-142"},["opening"]="Lydros wanted the water elemental in Dire Maul's eastern wing catalogued. A portion of Hydrospawn's essence would earn the visiting mage a useful cantrip.",["pending"]="{actor} meant to recover Hydrospawn's essence for Lydros.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Hydrospawn Essence in the Athenaeum.",["sourceHash"]="ab2c84f6c5a689a94be72236a4b9622d5d7d2b461540c49cee555eeb4361a24e",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7481]={["aftermath"]="Korolusk received the report as a tragedy, questioning the loss of the items and the absence of a trace of Kariel.",["atomIDs"]={"7481:description:1-143","7481:description:148-296","7481:description:301-403","7481:description:408-437","7481:description:439-504","7481:objective:1-38","7481:objective:40-128"},["endingAtomIDs"]={"7481:completion:1-10","7481:completion:12-21","7481:completion:23-49","7481:completion:51-70"},["opening"]="Korolusk traced Kariel's flight with ancient artifacts from Quel'Thalas to Feralas. He suspected sanctuary in Dire Maul and wanted news of the elf and his knowledge, alive or dead.",["pending"]="{actor} intended to search Dire Maul and report the findings to Korolusk.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned to Korolusk with the search's findings.",["sourceHash"]="43d6429d2c57b7bf8f530d6e412110e4bc28772c3cda8ae6e0d0f4fb21f7bebf",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7482]={["aftermath"]="Runethorn lamented the reported loss, asking after the items and the missing elf.",["atomIDs"]={"7482:description:1-143","7482:description:148-296","7482:description:301-403","7482:description:408-437","7482:description:439-504","7482:objective:1-38","7482:objective:40-131"},["endingAtomIDs"]={"7482:completion:1-10","7482:completion:12-21","7482:completion:23-49","7482:completion:51-70"},["opening"]="Runethorn's search for the elven master had reached Feralas. Kariel had fled with old artifacts, and the scholar hoped the halls of Dire Maul would yield news.",["pending"]="{actor} planned to search for Kariel and report to Runethorn.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the search's findings to Runethorn at Feathermoon.",["sourceHash"]="cb255168d7b56b33ce447ae39db5ebdb18ece37113c0800ff6a7a0c082b2d695",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7483]={["aftermath"]="Lydros produced the promised arcanum with little ceremony.",["atomIDs"]={"7483:description:1-62","7483:description:64-144","7483:description:146-169","7483:description:174-275","7483:description:280-285","7483:description:287-383","7483:description:385-401","7483:description:406-421","7483:objective:1-170"},["endingAtomIDs"]={"7483:completion:1-15","7483:completion:20-56","7483:completion:58-90","7483:completion:95-112"},["opening"]="Lydros recalled a lost libram that could place a minor haste charm on equipment. His uncertainty about its reagents was narrowed by a specific request for diamond, shards, and heroes' blood.",["pending"]="{actor} meant to bring the libram and its listed reagents to Lydros.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Lydros with the requested libram, diamond, shards, and blood.",["sourceHash"]="2dad145601a3e1b83d6ae1e03eb8ec8abf44e8b6eff59ef4656d194a2a821c00",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7484]={["aftermath"]="Lydros cautioned the recipient to take care while applying the enchantment.",["atomIDs"]={"7484:description:1-81","7484:description:83-122","7484:description:127-207","7484:description:212-253","7484:description:255-330","7484:description:335-468","7484:objective:1-163"},["endingAtomIDs"]={"7484:completion:1-54"},["opening"]="Lydros believed one of the Highborne spirits might hold the missing libram. Together with diamond, brilliant shards, and shadow skin, it could produce an arcanum for the magically inclined.",["pending"]="{actor} intended to deliver the libram and specified materials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Lydros the libram, diamond, four shards, and two shadow skins.",["sourceHash"]="25dfa7f2c484a979860dd118fa63da9e8fb9bacb83f4503a627eb80654d24990",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7485]={["aftermath"]="Lydros delivered the promised arcanum.",["atomIDs"]={"7485:description:1-50","7485:description:52-216","7485:description:218-230","7485:description:232-327","7485:description:332-477","7485:description:482-510","7485:objective:1-187"},["endingAtomIDs"]={"7485:completion:1-11","7485:completion:13-26","7485:completion:28-61"},["opening"]="Lydros scorned the lost libram despite recalling its owner's grief. He offered to recreate its arcanum from the text, a pristine diamond, brilliant shards, and abomination stitching.",["pending"]="{actor} planned to recover the libram and gather its reagents.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the libram, diamond, shards, and stitching to Lydros.",["sourceHash"]="8b8a1fb6e0a7eddc7ad4f1953a7fde22e5555bd1b3ee20b7f1596c8e8cc966b1",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7486]={["aftermath"]="Hydraxis urged a choice suited to protection against the Waterlords' foes.",["atomIDs"]={"7486:description:1-96","7486:description:101-201","7486:description:203-232","7486:description:237-311","7486:description:314-340","7486:description:342-348","7486:description:362-379","7486:objective:1-40"},["endingAtomIDs"]={"7486:completion:1-52","7486:completion:57-94","7486:completion:97-151"},["opening"]="Hydraxis conceded that services beyond expectation warranted a reward. A submerged coffer at the island's southern base held the promised acknowledgment.",["pending"]="{actor} intended to open Hydraxis's coffer.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} claimed the offered contents.",["sourceHash"]="61998435f77c1571f62ab1eac600d2f4097f5cdd5ad8fad51fa6dd6faa0c0ddf",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7488]={["aftermath"]="Latronicus regretted her death and planned to disperse the stored energies before destroying the device.",["atomIDs"]={"7488:description:1-133","7488:description:136-297","7488:description:302-314","7488:description:317-346","7488:description:349-411","7488:description:414-496","7488:objective:1-88"},["endingAtomIDs"]={"7488:completion:1-22","7488:completion:25-38","7488:completion:41-148","7488:completion:151-254","7488:completion:257-299","7488:completion:304-317","7488:completion:320-453"},["opening"]="Latronicus feared the harm Lethtendris could do with her web of stolen magical energy. He wanted the device recovered so the captured power could be released safely.",["pending"]="{actor} meant to retrieve the web for Latronicus.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Lethtendris's web at Feathermoon.",["sourceHash"]="a60288032d93f3e154cbff79943f9fcc4ab76a5905b54d76e1ec9b5c872f8f00",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7489]={["aftermath"]="Talo mourned her death but believed she would never have surrendered the device. He planned to send it to new wardens for study.",["atomIDs"]={"7489:description:1-53","7489:description:56-231","7489:description:234-315","7489:description:320-347","7489:description:350-507","7489:objective:1-69"},["endingAtomIDs"]={"7489:completion:1-23","7489:completion:25-200","7489:completion:202-291","7489:completion:296-309","7489:completion:311-385","7489:completion:387-428"},["opening"]="Talo feared Lethtendris's plan to turn Dire Maul's tainted power against her enemies. He wanted her web recovered and entrusted to more responsible students of magic.",["pending"]="{actor} intended to defeat Lethtendris and recover the web.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Lethtendris's web to Talo.",["sourceHash"]="604f6f897603523a390a548fc1930ea6a00f230aa72246a81669ca7417afc740",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7490]={["aftermath"]="Thrall acknowledged the Horde's victory and prepared to honor the service publicly.",["atomIDs"]={"7490:description:1-37","7490:description:39-104","7490:description:106-151","7490:objective:1-47"},["endingAtomIDs"]={"7490:completion:1-42","7490:completion:44-88","7490:completion:90-130"},["opening"]="The fallen brood mother's head was bound for the Warchief. Presenting it in Orgrimmar would carry news of the victory from the battlefield to the Horde's capital.",["pending"]="{actor} intended to take Onyxia's head to Thrall.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the head.",["sourceHash"]="19430c68dba3a7a7e83c9d423f6dcd37e41a497168ecbd5eb81dfe8ae46bce30",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7491]={["aftermath"]="Runthak announced the start of the celebration.",["atomIDs"]={"7491:description:1-63","7491:description:68-88","7491:description:93-130","7491:objective:1-52"},["endingAtomIDs"]={"7491:completion:1-74"},["opening"]="Thrall sent the next audience toward Runthak in the Valley of Strength. The public acknowledgment would follow the report of the brood mother's defeat.",["pending"]="{actor} planned to meet Runthak.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached the waiting overlord.",["sourceHash"]="fd70b6bcd0f07ffdd8e706350f245d1cc01475f3e4fbae25e30eef6b903a75e4",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7492]={["aftermath"]="Talo welcomed the answer and disclosed that the path led into Dire Maul.",["atomIDs"]={"7492:description:1-67","7492:description:70-158","7492:description:160-168","7492:description:173-192","7492:description:195-244","7492:objective:1-53"},["endingAtomIDs"]={"7492:completion:1-43","7492:completion:45-130","7492:completion:135-156"},["opening"]="Talo had requested agents for a delicate and dangerous matter in Feralas. Gorlach could give little detail beyond the summons to Camp Mojache.",["pending"]="{actor} planned to answer Talo's request.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Talo at Camp Mojache.",["sourceHash"]="41e025daf11c052be86e55d7781c3749edd0b0017693a3c2aa62811197dea3fe",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7494]={["aftermath"]="Latronicus welcomed the arrival while regretting the troubling cause of the meeting.",["atomIDs"]={"7494:description:6-35","7494:description:40-139","7494:description:142-224","7494:description:229-323","7494:description:328-346","7494:description:349-409","7494:objective:1-73"},["endingAtomIDs"]={"7494:completion:1-9","7494:completion:12-102","7494:completion:107-154"},["opening"]="Goodman announced the need to recover a dangerous magical item from a fugitive in Dire Maul. Latronicus awaited agents at Feathermoon to explain the task.",["pending"]="{actor} meant to meet Latronicus in Feralas.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Latronicus at Feathermoon.",["sourceHash"]="2f2a4250f9494d28e517d97cea9c06a7b621da61a50d0549efde3ac5b47990cd",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7495]={["aftermath"]="Fordragon treated the head's arrival as justice after years under Onyxia's influence. The city's response turned toward public celebration.",["atomIDs"]={"7495:description:1-37","7495:description:39-104","7495:description:106-150","7495:objective:1-66"},["endingAtomIDs"]={"7495:completion:1-56","7495:completion:58-123","7495:completion:125-166"},["opening"]="Onyxia's head was the evidence to be presented after the brood mother's fall. The destination was Fordragon in Stormwind, where the result could enter the kingdom's public account.",["pending"]="{actor} intended to take the Head of Onyxia to Bolvar.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Head of Onyxia to Highlord Bolvar Fordragon.",["sourceClassMask"]="?",["sourceHash"]="21f85af36e596ea7292af59b4f9aa263b9705afc0fc9eb5bb980aba703f29b6d",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[7496]={["aftermath"]="Mattingly prepared the ceremony after offering a choice of reward. The meeting carried the dragon's defeat into the Valley of Heroes.",["atomIDs"]={"7496:description:1-53","7496:description:55-81","7496:objective:1-49"},["bridge"]="Onyxia's head had reached Fordragon. The next meeting moved to Mattingly in the Valley of Heroes, where the kingdom was preparing its acknowledgment.",["bridgeFrom"]=7495,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"7496:completion:1-38","7496:completion:40-103"},["opening"]="Fordragon sent the next meeting to the Valley of Heroes. Major Mattingly was expecting the visitor after the dragon-head presentation.",["pending"]="{actor} planned to meet Major Mattingly.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Major Mattingly in the Valley of Heroes.",["sourceClassMask"]="?",["sourceHash"]="417399a4e23254a7bb00d8a653ed43a255619bf4707d6e34207c900ac84bfcac",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
