[7563]={["aftermath"]="Mor'zul planned to distill the blood for his parchment, while hinting that he might keep a little for himself.",["atomIDs"]={"7563:description:1-141","7563:description:144-227","7563:description:232-289","7563:description:292-419","7563:description:424-472","7563:description:475-489","7563:objective:1-88"},["endingAtomIDs"]={"7563:completion:1-14","7563:completion:16-104","7563:completion:106-195"},["opening"]="Mor'zul needed powerful glyphs to summon a beast from Xoroth. Their ink required blood from Winterspring's owl beasts, which he described as maddened by demonic emanations.",["pending"]="{actor} planned to gather thirty bottles of raging beast blood.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the thirty bottles to Mor'zul.",["sourceHash"]="015864a2e1ee95f9e69021484aad4673b12db7baad53a78e868170d24dfefbd8",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
