[7622]={["aftermath"]="Eris judged the trial worthy of Nordrassil's splinter, but warned that the Eye of Shadow still had to be found.",["atomIDs"]={"7622:description:1-97","7622:description:102-166","7622:description:168-248","7622:description:253-322","7622:description:324-353","7622:objective:1-37","7622:objective:39-96","7622:objective:101-170"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7622:completion:1-62","7622:completion:64-124","7622:completion:126-184","7622:completion:186-201"},["minimumStage"]=2,["objectiveSummary"]="Save fifty fleeing peasants before fifteen die, then speak to Eris.",["opening"]="Eris could not save the peasants cut down as they fled Stratholme. Protecting them as they walked toward the Light offered another chance to end the cursed existence she described, testing healing and resolve rather than a simple hunt.",["pending"]="{actor} would protect the fleeing peasants from their attackers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} saved the required peasants and returned to Eris.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="491109f6947fdee5fb85866b10ab46e380a5130160427450e27176b135221ea9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7623]={["aftermath"]="Banehollow allowed the audience but warned against wasting his patience.",["atomIDs"]={"7623:description:1-54","7623:description:57-99","7623:description:102-136","7623:description:141-240","7623:description:243-293","7623:description:298-408","7623:description:411-481","7623:objective:1-62","7623:objective:67-141"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7623:completion:1-40","7623:completion:43-109"},["minimumStage"]=2,["objectiveSummary"]="Use Gorzeeki's shadowy potions to reach Banehollow in Jaedenar.",["opening"]="A portal to Xoroth required rare stardust, and Banehollow was the likeliest source on Azeroth. Gorzeeki's potions could disguise the visitor in the Shadow Council's own corruption long enough to approach him.",["pending"]="{actor} would obtain the potions and seek Banehollow in Jaedenar.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Lord Banehollow under the potion's protection.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="f6e7503b62c3181697b40bdfa028a91dc3d1977b3819297eafa1622723787538",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7624]={["aftermath"]="The dreadlord savored the prospect of eating the heart and granted the visitor a little more patience.",["atomIDs"]={"7624:description:1-33","7624:description:36-52","7624:description:57-169","7624:description:172-237","7624:description:242-283","7624:description:286-350","7624:description:353-412","7624:description:415-449","7624:objective:1-80"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7624:completion:1-17","7624:completion:20-81","7624:completion:84-156","7624:completion:161-234","7624:completion:237-247"},["minimumStage"]=2,["objectiveSummary"]="Confront Ulathek and bring his heart to Banehollow.",["opening"]="Banehollow accused his servant of spying for Hel'nurath, a rival on Xoroth who wanted his power. Favor with the dreadlord now depended on confronting the suspected traitor in western Shadow Hold and carrying back his heart.",["pending"]="{actor} would confront Ulathek over Banehollow's accusation.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Ulathek's heart to Banehollow.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="2df178147cfe60d7bf6885aa519683bd97c7ed579d1e63b73ab5c96399ef3c06",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7625]={["aftermath"]="Gorzeeki could now supply Mor'zul's ink for the parchment that would open the way to Xoroth.",["atomIDs"]={"7625:description:1-45","7625:description:48-118","7625:description:121-187","7625:description:192-201","7625:description:204-256","7625:description:259-287","7625:description:289-313","7625:objective:1-40","7625:objective:43-95"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7625:completion:1-12","7625:completion:14-45","7625:completion:47-132","7625:completion:137-306"},["minimumStage"]=2,["objectiveSummary"]="Purchase Xorothian stardust from Ur'dan and deliver it to Gorzeeki.",["opening"]="Banehollow recognized the plan to steal a dreadsteed from his rival's domain. He permitted access to Ur'dan's stardust supply, though the visitor still had to meet the servant's price.",["pending"]="{actor} would buy Ur'dan's stardust for the portal preparations.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Xorothian stardust to Gorzeeki.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="2232b036584d6150a4fa5b512347f03aa9959dac1bce1be3b0e684621692d060",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7626]={["aftermath"]="Gorzeeki undertook to make the bell and hold it until the ritual was ready.",["atomIDs"]={"7626:description:1-143","7626:description:146-245","7626:description:250-364","7626:description:367-431","7626:objective:1-77"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7626:completion:1-10","7626:completion:12-56","7626:completion:58-119","7626:completion:124-189"},["minimumStage"]=2,["objectiveSummary"]="Bring Gorzeeki ten elixirs of shadow power for the summoning bell.",["opening"]="The bell named for Dethmoora Darkeyes was one of three instruments meant to conduct the summoning circle's arcane power. Gorzeeki could construct it only after receiving a substantial supply of an alchemist's shadow elixirs.",["pending"]="{actor} would obtain the elixirs for Gorzeeki's bell.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Gorzeeki with ten shadow-power elixirs.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="7357aeab9c96b42735ecaa1df9408e240cc51dd7fd84c6ec2f048c02cbf62673",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7627]={["aftermath"]="Gorzeeki promised to construct the wheel and keep it for the coming ritual.",["atomIDs"]={"7627:description:1-114","7627:description:117-248","7627:description:253-295","7627:objective:1-87"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7627:completion:1-15","7627:completion:17-138","7627:completion:140-191","7627:completion:193-263","7627:completion:265-293","7627:completion:298-323","7627:completion:325-401"},["minimumStage"]=2,["objectiveSummary"]="Supply six brilliant shards and twenty-five dark iron ore for the wheel.",["opening"]="The wheel was meant to contain and direct the summoning circle's violent energy. Its construction drew together an enchanter's shards and a miner's dark iron, making skilled trades part of the demonic ritual's preparation.",["pending"]="{actor} would gather the shards and ore for Gorzeeki.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the materials for the wheel.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="376f76dc147f0ad548e7d84a2621e28132d18472c6beac123cc4038c823f40d2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7628]={["aftermath"]="Gorzeeki accepted the scales and began preparing the instrument for the circle.",["atomIDs"]={"7628:description:1-84","7628:description:87-209","7628:description:214-308","7628:description:311-382","7628:objective:1-72"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7628:completion:1-14","7628:completion:16-66","7628:completion:68-209"},["minimumStage"]=2,["objectiveSummary"]="Bring Gorzeeki thirty-five black dragonscales for the candle.",["opening"]="The candle's stored fire was intended to burn demons that interfered with the summoning. Black dragonscale essence was needed to contain those flames safely within the ritual instrument.",["pending"]="{actor} would obtain the dragonscales for Gorzeeki.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the scales needed for the candle.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="fe39fdb2f7002bd1c5ce73860b8f7741b874d33838cbfd6adec5ffde594a94b6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7629]={["aftermath"]="Gorzeeki confirmed that J'eevee had completed the parchment and thanked the courier for returning his treasured jar.",["atomIDs"]={"7629:description:1-105","7629:description:108-113","7629:description:115-146","7629:description:149-175","7629:description:180-236","7629:description:239-309","7629:description:314-361","7629:description:364-405","7629:description:408-469","7629:objective:1-61","7629:objective:64-131"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7629:completion:1-9","7629:completion:11-40","7629:completion:42-65","7629:completion:67-92","7629:completion:94-114","7629:completion:116-140","7629:completion:145-194","7629:completion:196-225","7629:completion:227-248"},["minimumStage"]=2,["objectiveSummary"]="Release the jarred imp at Scholomance's alchemy lab and return the jar.",["opening"]="Gorzeeki lacked the equipment to infuse the portal parchment with stardust. Scholomance's alchemy laboratory could support the work, and a clever imp in a jar could perform it if carried safely to the lab.",["pending"]="{actor} would bring the imp to Scholomance's laboratory.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the jar after the imp prepared the parchment.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="2d51d82e416a869d47291d79acc2d42e6686497be161f05efaf8597c07a78690",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7630]={["aftermath"]="The bars allowed Gorzeeki to begin making the lodestone, another preparation for the Circle of Greater Summoning rather than the summoning itself.",["atomIDs"]={"7630:description:1-78","7630:description:81-184","7630:description:189-230","7630:description:233-248","7630:description:251-265","7630:description:267-316","7630:description:321-400","7630:objective:1-56"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7630:completion:1-11","7630:completion:13-24","7630:completion:26-56","7630:completion:58-209"},["minimumStage"]=2,["objectiveSummary"]="Bring three arcanite bars to Gorzeeki for a black lodestone.",["opening"]="The bell, wheel and candle were ready, but Gorzeeki still needed a safeguard for the summoning. A black lodestone could sustain the ritual objects if they faltered, and making it required arcanite.",["pending"]="{actor} would obtain arcanite for the ritual's lodestone.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Gorzeeki with the three arcanite bars.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="f9782ba59f9cc86fdfbd495384b3612fd7fe7262451d8a591bd191679c2cc771",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7631]={["aftermath"]="The beaten spirit imparted the dark knowledge of its summoning, though rage still stirred within the ghostly beast.",["atomIDs"]={"7631:description:1-30","7631:description:33-163","7631:description:165-191","7631:description:196-256","7631:description:259-338","7631:description:343-361","7631:description:364-442","7631:objective:1-28","7631:objective:31-100"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7631:completion:1-44","7631:completion:47-137","7631:completion:142-240"},["minimumStage"]=2,["objectiveSummary"]="Complete the summoning ritual, defeat the dreadsteed and bind its spirit.",["opening"]="The prepared instruments and stardust parchment could finally open the portal to Xoroth. Mor'zul demanded exact observance of his ritual instructions before the summoned dreadsteed could be confronted and bound.",["pending"]="{actor} would carry out Mor'zul's ritual and face the dreadsteed.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} defeated the summoned dreadsteed and bound its spirit.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="417cf0053b3e833c1834694668c5914191e3d179e5596b9517fa9529e911edfa",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7632]={["aftermath"]="The ancient recognized his own leaf and proposed that the return might begin a mutually useful service.",["atomIDs"]={"7632:description:1-47","7632:description:49-117","7632:description:122-214","7632:description:219-272","7632:objective:1-45","7632:objective:47-78"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7632:completion:1-36","7632:completion:38-50","7632:completion:52-77","7632:completion:82-114","7632:completion:119-170"},["minimumStage"]=2,["objectiveSummary"]="Find the ancient owner of the unusual petrified leaf.",["opening"]="A bright green leaf bore thick veins and deep wrinkles, suggesting an origin both ancient and powerful. Finding its owner could explain why so strange an object had survived.",["pending"]="{actor} would seek the leaf's original owner.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the leaf to its owner.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="a0af07f1838472689c151e30e1f9b880d367e05783ec533102d9601b42e5b579",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7634]={["aftermath"]="Hastat blessed the arrows the leaf-made quiver would protect and the struggle against the world's enemies.",["atomIDs"]={"7634:description:1-14","7634:description:16-44","7634:description:46-76","7634:description:81-197","7634:description:199-277","7634:description:282-361","7634:objective:1-75","7634:objective:77-135"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7634:completion:1-55","7634:completion:57-84","7634:completion:86-125"},["minimumStage"]=2,["objectiveSummary"]="Bring Hastat mature blue-dragon sinew in Felwood.",["opening"]="Hastat offered knowledge preserved across ages: with the right binding, one of his leaves could form an exceptional quiver. Sinew from an adult blue dragon was the material he required to apply that craft.",["pending"]="{actor} would seek blue-dragon sinew for Hastat's binding.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the mature blue-dragon sinew to Hastat.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="d3f9f7aa820b1504b513f7ab82c42bb466e7976327d1460ee2ca65a584241434",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7635]={["aftermath"]="Stoma found the material tainted with evil and began cleansing it before applying the enchantments.",["atomIDs"]={"7635:description:1-123","7635:description:128-157","7635:description:159-221","7635:description:223-320","7635:objective:1-75","7635:objective:77-134"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7635:completion:1-32","7635:completion:34-57","7635:completion:62-149"},["minimumStage"]=2,["objectiveSummary"]="Bring Stoma mature black-dragon sinew for the bowstring.",["opening"]="Vartrus could supply a stave, but Stoma alone offered the enchantment needed for its string. Mature black-dragon sinew would give him the material for an almost unbreakable binding.",["pending"]="{actor} would obtain black-dragon sinew for Stoma.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the sinew to Stoma.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="fa43bf275481a8a99ccfd996a70028c6711fa5b3b39b440c22eaa0a5ea3dd4b6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7636]={["aftermath"]="Vartrus offered a stave to be joined with Stoma's enchanted string, bringing the two crafts toward one weapon.",["atomIDs"]={"7636:description:1-63","7636:description:65-105","7636:description:107-147","7636:description:152-217","7636:description:219-280","7636:description:282-337","7636:description:339-399","7636:description:404-483","7636:description:485-505","7636:objective:1-56","7636:objective:61-82","7636:objective:87-106","7636:objective:111-129","7636:objective:134-158","7636:objective:163-248","7636:objective:253-332","7636:objective:337-376"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7636:completion:1-28","7636:completion:30-109","7636:completion:111-155"},["minimumStage"]=2,["objectiveSummary"]="Defeat Simone, Klinfran, Solenor and Artorius alone and return their heads.",["opening"]="Vartrus named four surviving agents of the Legion whose presence withered nature. They would flee a group but fight a solitary challenger, turning their arrogance into the condition of the trial he set.",["pending"]="{actor} would seek the four corrupters using Vartrus's bark for guidance.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the four demonic corrupters' heads to Vartrus.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="54a41bcdfc9347d9d01992aa8f13d725043e6c6e85dd633e75b9caa154a9a4dd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7637]={["aftermath"]="Rohan said the gift exceeded the loss of the censer and would also help Ironforge's people in need.",["atomIDs"]={"7637:description:1-93","7637:description:95-124","7637:description:129-195","7637:description:198-290","7637:description:295-346","7637:description:349-451","7637:description:456-489","7637:objective:1-64","7637:objective:67-133"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7637:completion:1-30","7637:completion:32-77","7637:completion:79-204","7637:completion:209-289"},["minimumStage"]=2,["objectiveSummary"]="Donate one hundred fifty gold for Rohan's exorcism censer.",["opening"]="Grayson insisted that a righteous purpose did not excuse taking another's tools without compensation. Obtaining Rohan's censer therefore began with a substantial donation, demonstrating the sacrifice expected of the paladin.",["pending"]="{actor} would visit Rohan in Ironforge with the donation.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} made the donation and obtained Rohan's censer.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="f3c85fa5416cdff98688395933055a8f8dfb3de8d4768b7f6fe7eb0ddb738fdb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7638]={["aftermath"]="Grayson warned that genuine obstacles lay ahead: the task was to save a companion, not merely pass another lesson.",["atomIDs"]={"7638:description:1-137","7638:description:139-151","7638:description:156-232","7638:description:235-381","7638:description:386-419","7638:description:422-463","7638:objective:1-72"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7638:completion:1-24","7638:completion:26-121","7638:completion:126-267","7638:completion:269-360","7638:completion:362-461","7638:completion:466-495"},["minimumStage"]=2,["objectiveSummary"]="Meet Grayson Shadowbreaker in Stormwind's Cathedral District.",["opening"]="Duthorian directed the long-awaited hope of a charger to Grayson. The promised undertaking concerned rescuing a future companion from evil, making the mount's acquisition a duty rather than a purchase.",["pending"]="{actor} would seek Grayson's guidance in Stormwind.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Lord Grayson Shadowbreaker.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="8ee62ac83469d4eb840083bf1a29842520d1847c3188b78d4d6211e32fdea46a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7639]={["aftermath"]="Grayson approved the sacrifice and identified the censer as the means of reaching the spirits in lands lost to darkness.",["atomIDs"]={"7639:description:1-35","7639:description:38-147","7639:description:152-209","7639:description:212-241","7639:objective:1-96"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7639:completion:1-18","7639:completion:20-159","7639:completion:161-248","7639:completion:250-289","7639:completion:294-352","7639:completion:354-468"},["minimumStage"]=2,["objectiveSummary"]="Carry Rohan's censer to Grayson in Stormwind.",["opening"]="Rohan entrusted a censer already used in several exorcisms to the next stage of Grayson's trial. Returning with it would move the preparation from sacrifice toward judgment of tormented spirits.",["pending"]="{actor} would bring the blessed censer to Grayson.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Rohan's censer to Grayson.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="407f99a693b0628f2e56d934a4878af34dbe4d6ae1d7289a9851d8cb9fa323d4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7640]={["aftermath"]="Grayson revealed the next purpose: reclaiming a fallen charger's spirit from Death Knight Darkreaver.",["atomIDs"]={"7640:description:1-108","7640:description:111-212","7640:description:215-377","7640:description:382-473","7640:objective:1-73","7640:objective:76-194"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7640:completion:1-14","7640:completion:16-234","7640:completion:239-411"},["minimumStage"]=2,["objectiveSummary"]="Draw out and defeat twenty-five Terrordale spirits with the censer.",["opening"]="Grayson attuned the censer with tainted soil from Terrordale. Green disturbances in the ground marked places where spiritual torment affected the living world, allowing the censer to expose the spirits for judgment.",["pending"]="{actor} would use the censer at Terrordale's disturbed ground.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the charge against Terrordale's spirits and returned to Grayson.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="5922a689d7c235a6ef04f6643c0ddbcd6eb9d6c0a5d6ff74382907c0580835f2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7641]={["aftermath"]="Grimand had received Grayson's message and accepted the commission, promising quality without pretending it would be cheap or easy.",["atomIDs"]={"7641:description:1-85","7641:description:88-274","7641:description:279-331","7641:description:334-425","7641:description:428-487","7641:description:490-504","7641:objective:1-58"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7641:completion:1-107","7641:completion:109-238","7641:completion:243-317","7641:completion:319-397"},["minimumStage"]=2,["objectiveSummary"]="Consult Grimand Elmore in Stormwind's Dwarven District.",["opening"]="The charger needed barding worthy of its quality and its passage through the spirit realm. Grayson recommended Grimand's craftsmanship while warning that such work would be expensive.",["pending"]="{actor} would commission the barding from Grimand.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} consulted Grimand in the Dwarven District.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="2e6d7bcbf2672691e301f672cf0704a8016b92f47d27bb5aa5cd4f8bf3f0a7f0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7642]={["aftermath"]="Grimand recognized that everything was ready and set about finishing the barding.",["atomIDs"]={"7642:description:1-197","7642:description:200-232","7642:description:234-249","7642:description:252-324","7642:description:329-390","7642:description:393-499","7642:objective:1-154"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7642:completion:1-7","7642:completion:9-44","7642:completion:47-90","7642:completion:95-153"},["minimumStage"]=2,["objectiveSummary"]="Supply Grimand with cloth, arcanite, Arthas' Tears, holy water and his fee.",["opening"]="Each part of the barding served a purpose: runecloth lined it, arcanite plated it, and the plant and holy water prepared its spiritual qualities. Grimand's payment covered labor, a saddle and stirrups as well as the craft itself.",["pending"]="{actor} would gather the specified materials and payment for Grimand.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Grimand's requested materials and fee.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="a7d3a86bcf7cdb6fe5ed336e3c986985fb4786926151c9cf7e50064f299338ca",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7643]={["aftermath"]="The spirit accepted the enchanted feed and positioned itself as if inviting the barding to be placed on its back.",["atomIDs"]={"7643:description:1-78","7643:description:81-137","7643:description:140-198","7643:description:201-239","7643:description:244-283","7643:description:286-342","7643:description:345-383","7643:description:386-454","7643:description:456-486","7643:objective:1-59","7643:objective:62-131","7643:objective:136-204","7643:objective:207-251","7643:objective:254-313","7643:objective:316-372"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7643:completion:1-154","7643:completion:156-292"},["minimumStage"]=2,["objectiveSummary"]="Free Tendris's captive equine spirit, soothe it with special feed and seek its blessing.",["opening"]="The barding needed a spirit's blessing, and Tendris Warpwood held the appropriate horse spirit captive in Dire Maul. Merideth's special feed would be needed after its release, because freedom alone would not soothe it enough to grant the blessing.",["pending"]="{actor} would free and feed the equine spirit before offering the barding.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} freed the equine spirit and presented the feed and barding.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="b652d6f4d95c9769bcfed3f90b9aa7d7874d5b9462f4868cb703af257f39873f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7644]={["aftermath"]="Grayson judged it ready to harness the charger after redemption, but one final instrument still had to be made.",["atomIDs"]={"7644:description:1-89","7644:description:92-233","7644:description:238-285","7644:description:288-379","7644:objective:1-110"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7644:completion:1-27","7644:completion:29-92","7644:completion:97-191","7644:completion:193-262","7644:completion:264-293","7644:completion:298-367","7644:completion:369-454"},["minimumStage"]=2,["objectiveSummary"]="Return the blessed barding to Grayson in Stormwind.",["opening"]="The barding glowed on the ancient horse spirit's back before returning to its bearer, apparently blessed. Grayson needed to inspect that preparation before the fallen charger's redemption could proceed.",["pending"]="{actor} would bring the blessed barding to Grayson.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the blessed barding to Grayson.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="76418579e06da38d381bf87a0a29962791776b3e63e77e71c61b410cc48d6cb2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7645]={["aftermath"]="The willingness to pay for a wrong someone else had committed changed Merideth's judgment. She offered future feed freely, while keeping the gold.",["atomIDs"]={"7645:description:1-123","7645:description:126-152","7645:description:155-182","7645:description:187-221","7645:description:223-243","7645:description:245-265","7645:description:268-363","7645:description:366-442","7645:description:447-494","7645:objective:1-157","7645:objective:160-221","7645:objective:226-295"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7645:completion:1-52","7645:completion:54-139","7645:completion:141-217","7645:completion:227-246","7645:completion:249-293","7645:completion:295-331","7645:completion:333-344","7645:completion:346-354","7645:completion:359-451"},["minimumStage"]=2,["objectiveSummary"]="Bring Merideth twenty Enriched Manna Biscuits and fifty gold for spiritual horse feed.",["opening"]="Merideth Carlson had been mocked for claiming she could nourish spiritual horses. She could prepare the feed, but demanded Argent Dawn manna biscuits and compensation for the humiliation she had endured.",["pending"]="{actor} would obtain the biscuits and payment for Merideth's feed.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Merideth with the manna biscuits and gold.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="bd1015fe25be5ad7152f4eb6862053bfc0de6a8f323363bd47cb66b4b0144eba",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7646]={["aftermath"]="Grayson identified the charger's remains in Scholomance's Great Ossuary and its soul's servitude to Darkreaver. The preparations were now directed at that specific rescue.",["atomIDs"]={"7646:description:1-118","7646:description:121-158","7646:description:161-276","7646:description:281-333","7646:description:336-436","7646:description:439-511","7646:objective:1-126"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7646:completion:1-65","7646:completion:67-99","7646:completion:104-193","7646:completion:195-231","7646:completion:233-318","7646:completion:320-402","7646:completion:404-483"},["minimumStage"]=2,["objectiveSummary"]="Bring Grayson an Azerothian diamond and a pristine black diamond.",["opening"]="The exorcism censer would become the catalyst of a divination scryer. Two contrasting diamonds were needed as its beacon, allowing the instrument to pierce the shadows surrounding the fallen charger.",["pending"]="{actor} would obtain the diamonds for Grayson's scryer.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the two diamonds to Grayson.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="834433d036546e6626f907e6c768b9dc6553d98294c867fb5c70d02cb884b8e2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7647]={["aftermath"]="Life returned to the charger's eyes and it nuzzled the rescuer's hand, released from the burdens of its former service.",["atomIDs"]={"7647:description:1-68","7647:description:73-195","7647:description:198-288","7647:description:291-391","7647:description:394-480","7647:description:485-494","7647:objective:1-90","7647:objective:93-145","7647:objective:148-213","7647:objective:216-274","7647:objective:279-376"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7647:completion:1-112","7647:completion:114-233","7647:completion:235-317","7647:completion:319-418","7647:completion:423-461","7647:completion:463-478"},["minimumStage"]=2,["objectiveSummary"]="Use the scryer in the Great Ossuary, defeat Darkreaver and redeem his charger.",["opening"]="Grayson's scryer would call accursed spirits from the ossuary's depths. Judging them would draw out Darkreaver, whose defeat was necessary to recover the charger's soul and free it from service to the death knight.",["pending"]="{actor} would undertake the ossuary trial and seek the charger's lost soul.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} defeated Darkreaver and restored the charger's redeemed soul with its blessed barding.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="db046d5646a961ae4c786b068073c8bac5b3270d5cf83e0e4fd929fc177d3513",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7648]={["aftermath"]="Grayson praised the craftsmanship but required an appropriate blessing before it could be used on the charger.",["atomIDs"]={"7648:description:1-67","7648:description:72-96","7648:description:99-228","7648:description:231-291","7648:description:296-358","7648:description:361-436","7648:objective:1-109"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7648:completion:1-29","7648:completion:31-106","7648:completion:108-234","7648:completion:239-348","7648:completion:350-456","7648:completion:458-494"},["minimumStage"]=2,["objectiveSummary"]="Take Grimand's finished barding to Grayson for inspection.",["opening"]="Grimand considered the work equal to the barding he had once made for Grayson's own charger. The completed craft now needed the patron's inspection before it could serve a steed with such unusual spiritual needs.",["pending"]="{actor} would carry Grimand's barding to Grayson.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented the finished barding to Grayson.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="3d23921422ecaf5cb87fae9d1545d2f61aa0836c48c358f1c9a8bbf6277212ae",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7649]={["aftermath"]="Lydros removed a recipe page from the returned book and offered its use in gratitude.",["atomIDs"]={"7649:description:1-43","7649:objective:1-39"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7649:completion:1-18","7649:completion:23-73","7649:completion:78-119"},["minimumStage"]=2,["objectiveSummary"]="Return the marked armor-crafting book to the Athenaeum.",["opening"]="The recovered book carried the Athenaeum's mark, pointing toward its rightful custodians. Returning it offered a chance to restore part of their scattered library.",["pending"]="{actor} would return the marked book to its owners.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the first armor-crafting volume to Lydros.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="42a61b614ac5587f4229b6989546d5590e3b455edfb18430531c559c0f98ff31",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[7650]={["aftermath"]="Lydros offered a recipe page from the recovered book.",["atomIDs"]={"7650:description:1-43","7650:objective:1-39"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7650:completion:1-18","7650:completion:23-73","7650:completion:78-119"},["minimumStage"]=2,["objectiveSummary"]="Return the second marked armor-crafting volume to the Athenaeum.",["opening"]="The second volume bore the same Athenaeum mark, identifying the library to which it belonged. Its recovery called for restitution rather than keeping an ownerless prize.",["pending"]="{actor} would restore the second volume to the Athenaeum.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the second armor-crafting volume to Lydros.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="8dfd3c1fd3f3bf8d96f835a6376e8e28374a38d9f05c6c502e8d0e122ff7811e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
