[7667]={["aftermath"]="Sagorne could complete the first scryer and expected to make others without more diamonds. He then offered a further task against a danger to the spirit realm.",["atomIDs"]={"7667:description:1-58","7667:description:60-91","7667:description:94-113","7667:description:118-205","7667:description:208-285","7667:description:288-374","7667:description:377-453","7667:description:458-495","7667:objective:1-146"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7667:completion:1-33","7667:completion:35-64","7667:completion:69-191","7667:completion:193-249","7667:completion:251-298","7667:completion:300-377"},["minimumStage"]=2,["objectiveSummary"]="Supply Sagorne with an Azerothian diamond and a pristine black diamond.",["opening"]="Sagorne needed a device capable of piercing the shadows in Scholomance's Great Ossuary, but lacked the two costly diamonds required to finish it. He asked for material help in an undertaking he regarded as spiritually urgent.",["pending"]="{actor} would bring Sagorne the two diamonds in Orgrimmar.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the diamonds for Sagorne's divination scryer.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="501c1a327686b48b3f3abe04ff5b953e9e177b718adece739d77ce62c230b208",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
