[7703]={["aftermath"]="Kromcrush recognized an ancient magical mark and offered to restore its power, accepting the recovery as proof of rightful rule.",["atomIDs"]={"7703:description:1-103","7703:description:106-233","7703:description:238-284","7703:description:287-356","7703:description:359-481","7703:description:484-499","7703:objective:1-82","7703:objective:87-239"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"7703:completion:1-6","7703:completion:8-37","7703:completion:39-83","7703:completion:85-127","7703:completion:129-172","7703:completion:174-200","7703:completion:205-299","7703:completion:301-432","7703:completion:437-467","7703:completion:469-508"},["minimumStage"]=2,["objectiveSummary"]="Recover the Gauntlet of Gordok Might for Captain Kromcrush.",["opening"]="Kromcrush's old stories made recovery of the stolen gauntlet a sign of the Gordok's true ruler. He blamed Tortheldrin for taking it from an earlier king and hoped the new claimant could succeed where others had failed.",["pending"]="{actor} would seek the stolen gauntlet in Dire Maul.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the Gauntlet of Gordok Might to Kromcrush.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="30ec8c2fbcfbb917e18eb4504f998c6afcea32b48cda0902a86fd5d70162af28",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
