[7721]={["atomIDs"]={"7721:description:1-151","7721:description:154-203","7721:description:208-391","7721:description:394-462","7721:objective:1-177"},["opening"]="The coastal elementals were another obstacle to Zorbin's shop, but their cores offered power for his Ultra-Shrinker refinements. He wanted ten saved from the creatures along the shore.",["pending"]="{actor} meant to gather ten Water Elemental Cores for Zorbin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered ten Water Elemental Cores to Zorbin Fandazzle.",["sourceClassMask"]="?",["sourceHash"]="a64dfbddb6a246caea15ec7a84b9ef49f56f9933e4487e59f1b7bcee54d60299",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
